public void iterateSimplex(List<RealVector> initialGuess, Simplex simplex, MultivariateFunction evaluator, Comparator<RealPointValuePair> comparator) {
    simplex.sortVertices(comparator);
    RealPointValuePair best = simplex.getPoint(0);
    RealPointValuePair worst = simplex.getPoint(simplex.getSize() - 1);
    RealPointValuePair nextToWorst = simplex.getPoint(simplex.getSize() - 2);
    RealVector centroid = computeCentroid(simplex, simplex.getSize() - 1);
    RealVector reflected = centroid.add(centroid.subtract(worst.getPoint()));
    double reflectedValue = evaluator.value(reflected.toArray());
    if (reflectedValue < best.getValue()) {
        RealVector expanded = centroid.add(reflected.subtract(centroid).mapMultiply(ReflectionExpansionFactor));
        double expandedValue = evaluator.value(expanded.toArray());
        if (expandedValue < reflectedValue) {
            simplex.setPoint(simplex.getSize() - 1, new RealPointValuePair(expanded, expandedValue));
        } else {
            simplex.setPoint(simplex.getSize() - 1, new RealPointValuePair(reflected, reflectedValue));
        }
    } else {
        if (reflectedValue < nextToWorst.getValue()) {
            simplex.setPoint(simplex.getSize() - 1, new RealPointValuePair(reflected, reflectedValue));
        } else {
            RealVector contracted;
            double contractedValue;
            if (reflectedValue < worst.getValue()) {
                contracted = centroid.add(reflected.subtract(centroid).mapMultiply(OutsideContractionFactor));
                contractedValue = evaluator.value(contracted.toArray());
            } else {
                contracted = centroid.subtract(centroid.subtract(worst.getPoint()).mapMultiply(InsideContractionFactor));
                contractedValue = evaluator.value(contracted.toArray());
            }
            if (contractedValue < worst.getValue()) {
                simplex.setPoint(simplex.getSize() - 1, new RealPointValuePair(contracted, contractedValue));
            } else {
                shrinkSimplex(simplex, best, evaluator);
            }
        }
    }
}

